import json
from pathlib import Path
import sqlite3

import config
import uniclubs_database
import uniclubs_export
import uniclubs_importer


def read_public_export(path):
    """Read an existing bounded snapshot; missing means bootstrap, damaged means failure."""
    path = Path(path)
    if not path.exists():
        return None
    if path.stat().st_size > config.UNICLUBS_MAX_EXPORT_BYTES:
        raise ValueError('The public catalog snapshot exceeds its size limit.')
    try:
        payload = json.loads(path.read_text(encoding='utf-8'))
    except (ValueError, UnicodeDecodeError) as error:
        raise ValueError('The existing public catalog snapshot is not valid JSON.') from error
    return uniclubs_export.validate_export(payload)


def _restore_if_needed(connection, document):
    """Restore fresh runners while refusing to overwrite a newer public snapshot."""
    occupied = connection.execute('''SELECT EXISTS (SELECT 1 FROM clubs)
        OR EXISTS (SELECT 1 FROM events) OR EXISTS (SELECT 1 FROM import_log)''').fetchone()[0]
    if not occupied:
        uniclubs_export.restore_export(connection, document)
        return
    local_success = connection.execute('''SELECT MAX(imported_at_utc) FROM import_log
        WHERE status='success' ''').fetchone()[0]
    if local_success is None or local_success < document['_meta']['last_success_utc']:
        raise ValueError('The local catalog is older than the snapshot; use a fresh catalog.')


def refresh_export(connection, path=config.UNICLUBS_EXPORT_FILE, now=None):
    """Perform one verified refresh, keeping the prior public file if any step fails.

    :param connection: initialized, idle independent UniClubs catalog
    :param path: public JSON destination, also used to restore a fresh runner's catalog
    :param now: optional aware clock passed to the source synchronization
    :return: source synchronization counters and counts, without full source records
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before refreshing the public catalog.')
    previous = read_public_export(path)
    if previous is not None:
        _restore_if_needed(connection, previous)
    result = uniclubs_importer.run_sync(connection, now=now)
    uniclubs_export.write_export(connection, path)
    # Course: L04 – explicit keys keep raw source objects out of the command summary.
    return {key: value for key, value in result.items()
            if key not in ('clubs', 'events', 'source_clubs', 'source_events')}


if __name__ == '__main__':
    catalog = uniclubs_database.get_connection()
    try:
        uniclubs_database.init_db(catalog)
        summary = refresh_export(catalog)
        uniclubs_export.write_sqlite(catalog)
        print(f'Public UniClubs export: {config.UNICLUBS_EXPORT_FILE}')
        print(f'Events: {summary["events_added"]} added, {summary["events_updated"]} updated, '
              f'{summary["events_unchanged"]} unchanged.')
    except (ValueError, sqlite3.Error, OSError) as error:
        print(f'Public catalog refresh failed: {error}')
        raise SystemExit(1)
    finally:
        catalog.close()
